import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes in a weighted directed graph.

    Args:
        edges (list): List of tuples (from_node, to_node, weight)
        start (str/any): Starting node
        end (str/any): Ending node

    Returns:
        tuple: (distance, path) or (None, None) if no route exists.

    Raises:
        ValueError: If any edge has a negative weight.
    """
    # Case when start and end are the same
    if start == end:
        return (0, [start])

    # Build adjacency list from edges
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Validate all edge weights are non-negative
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Edge with negative weight is not allowed")

    # Dijkstra's Algorithm
    distances = {start: 0}
    predecessors = {start: None}
    heap = [(0, start)]
    visited = set()

    while heap:
        dist, current = heapq.heappop(heap)

        if current in visited:
            continue
        visited.add(current)

        # Optimization: stop early if target is reached
        if current == end:
            break

        # Explore neighbors
        for neighbor, weight in graph.get(current, []):
            new_dist = dist + weight
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                predecessors[neighbor] = current
                heapq.heappush(heap, (new_dist, neighbor))

    # If the end node was not visited, return None path
    if end not in visited:
        return (None, None)

    # Reconstruct the path from start to end
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessors[current]

    path.reverse()

    return (distances[end], path)
